1	import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
2	import { join } from 'node:path';
3	import { parseChange, parseRiskIds, parseSpec } from './parse.mjs';
4	
5	export const BUDGET = {
6	  fix: { lines: 40, tasks: 5 },
7	  change: { lines: 120, tasks: 14 },
8	  feature: { lines: 250, tasks: 30 },
9	};
10	const SECTIONS = { fix: ['Cause', 'Tasks'], change: ['Why', 'Requirements', 'Design', 'Risks', 'Tasks'], feature: ['Why', 'Requirements', 'Design', 'Risks', 'Tasks'] };
11	const FREE_TAGS = ['verify', 'regression'];
12	const SCENARIO = /^- Scenario: .*\bWHEN\b.*\bTHEN\b/;
13	
14	const prefixOf = (id) => id.split('-')[0];
15	
16	export const changesDir = (root) => join(root, 'cr', 'changes');
17	export const specsDir = (root) => join(root, 'cr', 'specs');
18	
19	export const activeChangeIds = (root) =>
20	  existsSync(changesDir(root))
21	    ? readdirSync(changesDir(root)).filter((name) => name !== 'archive' && statSync(join(changesDir(root), name)).isDirectory())
22	    : [];
23	
24	export const loadSpecs = (root) =>
25	  existsSync(specsDir(root))
26	    ? readdirSync(specsDir(root))
27	        .filter((name) => name.endsWith('.md'))
28	        .map((name) => ({ file: `cr/specs/${name}`, name: name.replace(/\.md$/, ''), ...parseSpec(readFileSync(join(specsDir(root), name), 'utf8')) }))
29	    : [];
30	
31	const checkRequirementBody = (item, errors) => {
32	  if (!item.body.some((line) => /\bSHALL\b/.test(line))) {
33	    errors.push(`${item.id} has no SHALL statement`);
34	  }
35	  if (!item.body.some((line) => SCENARIO.test(line))) {
36	    errors.push(`${item.id} has no "- Scenario: … WHEN … THEN …" line`);
37	  }
38	};
39	
40	export const validateSpecs = (specs) => {
41	  const errors = [];
42	  const owners = new Map();
43	  for (const spec of specs) {
44	    const report = (message) => errors.push(`${spec.file}: ${message}`);
45	    if (spec.capability !== spec.name) {
46	      report(`first line must be "# ${spec.name}"`);
47	    }
48	    for (const item of spec.requirements) {
49	      if (owners.has(item.id)) {
50	        report(`${item.id} is defined twice (also in ${owners.get(item.id)})`);
51	      }
52	      owners.set(item.id, spec.file);
53	      const local = [];
54	      checkRequirementBody(item, local);
55	      local.forEach(report);
56	    }
57	  }
58	  return errors;
59	};
60	
61	const checkDeltas = (change, specs, errors) => {
62	  const living = new Map(specs.flatMap((spec) => spec.requirements.map((item) => [item.id, spec.name])));
63	  const prefixOwner = new Map(specs.flatMap((spec) => spec.requirements.map((item) => [prefixOf(item.id), spec.name])));
64	  const seen = new Set();
65	  for (const item of change.requirements) {
66	    if (seen.has(item.id)) {
67	      errors.push(`${item.id} appears twice in Requirements`);
68	    }
69	    seen.add(item.id);
70	    const owner = prefixOwner.get(prefixOf(item.id));
71	    if (owner && owner !== item.capability) {
72	      errors.push(`${item.id}: prefix ${prefixOf(item.id)} already belongs to ${owner}`);
73	    }
74	    prefixOwner.set(prefixOf(item.id), owner ?? item.capability);
75	    if (item.op === 'ADDED' && living.has(item.id)) {
76	      errors.push(`ADDED ${item.id} already exists in ${living.get(item.id)}`);
77	    }
78	    if (item.op !== 'ADDED' && living.get(item.id) !== item.capability) {
79	      errors.push(`${item.op} ${item.id} does not exist in ${item.capability}`);
80	    }
81	    if (item.op !== 'REMOVED') {
82	      checkRequirementBody(item, errors);
83	    }
84	  }
85	};
86	
87	const checkTasks = (change, errors) => {
88	  const requirementIds = new Set(change.requirements.map((item) => item.id));
89	  const applyingRisks = new Set(change.risks.filter((risk) => risk.applies === 'yes').map((risk) => risk.id));
90	  const referenced = new Set();
91	  const fileTracks = new Map();
92	  for (const task of change.tasks) {
93	    if (task.malformed) {
94	      errors.push(`malformed task line: "${task.malformed}" (expected "- [ ] T01 @track [refs] text | files")`);
95	      continue;
96	    }
97	    for (const ref of task.refs) {
98	      referenced.add(ref);
99	      const known = FREE_TAGS.includes(ref) || requirementIds.has(ref) || applyingRisks.has(ref);
100	      if (!known) {
101	        errors.push(`${task.id} references unknown "${ref}"`);
102	      }
103	    }
104	    for (const file of task.track === 'main' ? [] : task.files) {
105	      const other = fileTracks.get(file);
106	      if (other && other !== task.track) {
107	        errors.push(`${file} is listed in tracks ${other} and ${task.track}`);
108	      }
109	      fileTracks.set(file, other ?? task.track);
110	    }
111	  }
112	  for (const id of requirementIds) {
113	    if (!referenced.has(id)) {
114	      errors.push(`${id} has no task`);
115	    }
116	  }
117	  if (change.tier === 'fix' && !referenced.has('regression')) {
118	    errors.push('a fix needs a task tagged [regression]');
119	  }
120	};
121	
122	const checkRisks = (change, riskIds, errors) => {
123	  const taskIds = new Set(change.tasks.map((task) => task.id));
124	  for (const id of riskIds) {
125	    const rows = change.risks.filter((risk) => risk.id === id);
126	    if (rows.length !== 1 && change.tier !== 'fix') {
127	      errors.push(rows.length ? `Risks table lists ${id} ${rows.length} times` : `Risks table is missing ${id}`);
128	    }
129	  }
130	  for (const risk of change.risks) {
131	    if (!riskIds.includes(risk.id)) {
132	      errors.push(`${risk.id} is not in cr/risks.md`);
133	    } else if (risk.applies === 'yes' && !taskIds.has(risk.task)) {
134	      errors.push(`${risk.id} applies but task "${risk.task}" does not exist`);
135	    } else if (risk.applies === 'no' && !risk.note) {
136	      errors.push(`${risk.id} does not apply but gives no reason`);
137	    }
138	  }
139	};
140	
141	export const validateChange = (change, folder, { specs, riskIds, strict }) => {
142	  const errors = [];
143	  if (change.id !== folder) {
144	    errors.push(`title id "${change.id}" does not match folder "${folder}" (first line: "# ${folder}: <title>")`);
145	  }
146	  if (!BUDGET[change.tier]) {
147	    errors.push('Tier must be feature, change or fix');
148	    return errors;
149	  }
150	  for (const section of SECTIONS[change.tier]) {
151	    if (!change.sections.includes(section)) {
152	      errors.push(`missing section "## ${section}"`);
153	    }
154	  }
155	  if (change.tier !== 'fix' && change.requirements.length === 0) {
156	    errors.push('Requirements has no "#### <ID>: <name>" block under an ADDED, MODIFIED or REMOVED heading');
157	  }
158	  checkDeltas(change, specs, errors);
159	  checkRisks(change, riskIds, errors);
160	  checkTasks(change, errors);
161	  const budget = BUDGET[change.tier];
162	  const article = change.tier === 'fix' ? 'a fix' : `a ${change.tier}`;
163	  if (change.lineCount > budget.lines) {
164	    errors.push(`${change.lineCount} lines, budget for ${article} is ${budget.lines}: cut restatement, refer to requirements by id`);
165	  }
166	  if (change.tasks.length > budget.tasks) {
167	    errors.push(`${change.tasks.length} tasks, budget for ${article} is ${budget.tasks}`);
168	  }
169	  if (change.tasks.length === 0) {
170	    errors.push('Tasks has no task line');
171	  } else if (strict && change.tasks.every((task) => task.done)) {
172	    errors.push('every task is ticked but the change is not archived: run "node cr/bin/cr.mjs archive"');
173	  }
174	  return errors;
175	};
176	
177	export const readChange = (root, id) => parseChange(readFileSync(join(changesDir(root), id, 'change.md'), 'utf8'));
178	
179	export const validateRepo = (root, { id, strict = false } = {}) => {
180	  const specs = loadSpecs(root);
181	  const risksPath = join(root, 'cr', 'risks.md');
182	  const riskIds = existsSync(risksPath) ? parseRiskIds(readFileSync(risksPath, 'utf8')) : [];
183	  const errors = validateSpecs(specs);
184	  for (const folder of id ? [id] : activeChangeIds(root)) {
185	    const file = `cr/changes/${folder}/change.md`;
186	    if (!existsSync(join(root, file))) {
187	      errors.push(`${file}: not found`);
188	      continue;
189	    }
190	    errors.push(...validateChange(readChange(root, folder), folder, { specs, riskIds, strict }).map((message) => `${file}: ${message}`));
191	  }
192	  return errors;
193	};
194

